 static hid_t get_hdf5type_acquisitionheader(void) {
     hid_t datatype;
     herr_t h5status;
     hsize_t arraydims[1];
     hid_t vartype;

     datatype = H5Tcreate(H5T_COMPOUND, sizeof(ISMRMRD_AcquisitionHeader));
